def join(*paths):
    """Join multiple path strings into a single normalized path."""
    if not paths:
        return ""

    path = paths[0]
    for component in paths[1:]:
        if component.startswith("/"):
            path = component
        else:
            path += "/" + component

    return normpath(path)

def join(*paths):
    """Join paths, discarding previous segments when an absolute path occurs."""
    path = ""

    for component in paths:
        if component.startswith("/"):
            path = component
        elif component:
            if path:
                path += "/" + component
            else:
                path = component

    return normpath(path) if path else ""

def join(*paths):
    """Join paths and normalize the resulting path.

    An absolute path discards all segments joined before it.
    """
    path = ""

    for component in paths:
        if component.startswith("/"):
            path = component
        elif component:
            path = component if not path else path + "/" + component

    return normpath(path)

def make_safe_absolute_uri(base, rel=None):
    """Join a base URI and relative URI, returning only safe absolute URIs."""
    if base is None:
        base = ''
    if rel is None:
        rel = ''

    try:
        base = convert_to_idn(base)
        rel = convert_to_idn(rel)
    except (UnicodeEncodeError, ValueError):
        return ''

    uri = _urljoin(base, rel)

    # Escape spaces in HTTP(S) URLs.
    if uri.lower().startswith(('http://', 'https://')):
        uri = uri.replace(' ', '%20')

    # A URI without a scheme cannot be made absolute without a base.
    if ':' not in uri:
        uri = _urljoin('http://example.com/', uri)
        if not uri.startswith('http://example.com/'):
            return ''
        uri = uri[len('http://example.com'):]

    scheme = uri.split(':', 1)[0].lower()
    if scheme not in ACCEPTABLE_URI_SCHEMES:
        return ''

    return uri

