def make_safe_absolute_uri(base, rel=None):
    """Join a base URL and relative URL, allowing only acceptable URI schemes."""

    def _has_acceptable_scheme(uri, require_scheme=False):
        if not uri:
            return False

        if ':' not in uri:
            return not require_scheme

        scheme = uri.split(':', 1)[0].lower()
        return scheme in ACCEPTABLE_URI_SCHEMES

    # With no base URL, preserve the relative URL exactly as provided.
    if not base:
        return rel or ''

    # With no relative URL, preserve a valid base URL exactly as provided.
    if not rel:
        if not isinstance(base, str):
            return ''
        return base if _has_acceptable_scheme(base, require_scheme=True) else ''

    try:
        base = convert_to_idn(base)
        rel = convert_to_idn(rel)
        uri = _urljoin(base, rel)
    except (TypeError, UnicodeEncodeError, ValueError):
        return ''

    if uri.lower().startswith(('http://', 'https://')):
        uri = uri.replace(' ', '%20')

    # The joined result must have an acceptable absolute URI scheme.
    if not _has_acceptable_scheme(uri, require_scheme=True):
        return ''

    return uri

def make_safe_absolute_uri(base, rel=None):
    """Join a base URL and relative URL, optionally validating its scheme."""
    if not base:
        return rel or ''

    if not rel:
        uri = base
    else:
        try:
            base = convert_to_idn(base)
            rel = convert_to_idn(rel)
            uri = _urljoin(base, rel)
        except (TypeError, UnicodeEncodeError, ValueError):
            return ''

    acceptable_schemes = globals().get('ACCEPTABLE_URI_SCHEMES')

    # An empty or undefined scheme list disables scheme validation.
    if acceptable_schemes:
        if ':' not in uri:
            return ''

        scheme = uri.split(':', 1)[0].lower()
        if scheme not in acceptable_schemes:
            return ''

    return uri

