def add(self, translations, merge=True):
        """Add a translation catalog to this catalog.

        If ``merge`` is true, translations for an existing domain are merged
        into that domain. Otherwise, the existing domain is replaced.
        """
        domain = translations.domain

        if domain == self.DEFAULT_DOMAIN and self.plural is DEFAULT_PLURAL:
            self.plural = translations.plural

        if domain == self.domain:
            if merge:
                self._catalog.update(translations._catalog)
                self.files.extend(translations.files)
            else:
                self._catalog = translations._catalog
                self.files = list(translations.files)
                self.plural = translations.plural
            return

        existing = self._domains.get(domain)

        if merge and existing is not None:
            existing._catalog.update(translations._catalog)
            existing.files.extend(translations.files)
        else:
            self._domains[domain] = translations

