def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    matches = []

    subtable = relevant_l33t_subtable(password, _l33t_table)
    if not subtable:
        return matches

    for substitution in enumerate_l33t_subs(subtable):
        translated_password = translate(password, substitution)

        for dictionary_match_result in dictionary_match(
                translated_password,
                _ranked_dictionaries=_ranked_dictionaries):

            i = dictionary_match_result['i']
            j = dictionary_match_result['j']

            original_token = password[i:j + 1]
            translated_token = translated_password[i:j + 1]

            # Exclude single-character matches.
            if len(original_token) <= 1:
                continue

            # Keep only substitutions that affect this matched token.
            used_substitutions = {
                l33t_char: replacement
                for l33t_char, replacement in substitution.items()
                if l33t_char in original_token
            }

            # Exclude direct dictionary matches where no actual l33t
            # substitution changed the matched token.
            if (
                not used_substitutions
                or original_token.lower() == translated_token.lower()
            ):
                continue

            match = dict(dictionary_match_result)
            match.update({
                'token': original_token,
                'original_token': original_token,
                'matched_word': dictionary_match_result['matched_word'],
                'i': i,
                'j': j,
                'position': {
                    'i': i,
                    'j': j,
                },
                'sub': used_substitutions,
                'l33t_substitutions': used_substitutions,
                'l33t': True,
            })

            matches.append(match)

    return sorted(
        matches,
        key=lambda match: (
            match['i'],
            match['j'],
            match['matched_word'],
            sorted(match['l33t_substitutions'].items()),
        ),
    )

