def update(self, iterable):
        """Add key-value pairs from *iterable*.

        If *iterable* is another :class:`ManyToMany` instance, all of its
        relationships are merged into this instance. Existing relationships
        are preserved, and both the forward and inverse mappings remain
        synchronized.
        """
        if isinstance(iterable, ManyToMany):
            for key, values in iterable.data.items():
                for value in values:
                    self.add(key, value)
            return

        for key, value in iterable:
            self.add(key, value)

def update(self, iterable):
        """Merge relationships from another mapping or iterable.

        A mapping should map each key to an iterable of related values.
        Existing relationships are preserved, and inverse mappings remain
        synchronized.
        """
        if isinstance(iterable, ManyToMany):
            for key, values in iterable.data.items():
                self[key] = values
        elif hasattr(iterable, 'keys'):
            for key in iterable.keys():
                self[key] = iterable[key]
        else:
            for key, value in iterable:
                self.add(key, value)

