        Existing relationships are preserved. Mapping values are treated as
        iterables of related values, while an iterable of ``(key, value)``
        tuples adds each relationship individually.
        """
        if isinstance(iterable, ManyToMany):
            for key, values in iterable.data.items():
                for value in values:
