def get_tunings(instrument=None, nr_of_strings=None, nr_of_courses=None):
    """Return a list of all tunings that satisfy the given constraints.

    The instrument parameter is treated as a case-insensitive prefix. If it is
    None, tunings for all instruments are returned.
    """
    result = []

    if instrument is None:
        instrument_keys = list(_known.keys())
    else:
        searchi = str.upper(instrument)
        instrument_keys = [
            key for key in _known if key.startswith(searchi)
        ]

    for key in instrument_keys:
        for tuning in six.itervalues(_known[key][1]):
            if (
                nr_of_strings is not None
                and tuning.count_strings() != nr_of_strings
            ):
                continue

            if (
                nr_of_courses is not None
                and tuning.count_courses() != nr_of_courses
            ):
                continue

            result.append(tuning)

    return result

